// Friendly names for the generated API contract (never edit lib/generated by hand:
// `npm run gen:types` rebuilds it from contracts/, and CI fails if it is stale).
import type { components } from "./generated/api";
import type { AgentEvent } from "./generated/events";

type S = components["schemas"];

export type Thread = S["Thread"];
export type ThreadDetail = S["ThreadDetail"];
export type GraphJSON = S["GraphJSON"];
export type Evidence = S["Evidence"];
export type Citation = S["Citation"];
export type PlanStep = S["PlanStep"];
export type StepResult = S["StepResult"];

export type { AgentEvent };
export type EventKind = AgentEvent["event"];
export type EventOf<K extends EventKind> = Extract<AgentEvent, { event: K }>;
